"""Audit Network v6 and build a narrowly scoped, leakage-checked v7 patch dataset."""
import hashlib, json, math, re
from collections import Counter
from difflib import SequenceMatcher
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
V6=ROOT/'.data/training/user-proposed-prepared-network-v6'
V7=ROOT/'.data/training/user-proposed-prepared-network-v7'
